# Generated by build.py from recipe.yml for recipe smtp-forward-mail-with-an-alias. Do not edit.
set -e
cd "$(dirname "$0")"
surl --mail-domain example.com --mailbox form@example.com:formpass --mailbox ann@example.com:annpass --mailbox bob@example.com:bobpass --mail-alias "support@example.com=ann@example.com,bob@example.com" smtp://127.0.0.1:8080/ imap://127.0.0.1:8081/ &
sleep 1
curl -sS --crlf -u form@example.com:formpass --mail-from form@example.com --mail-rcpt support@example.com -T help.eml smtp://127.0.0.1:8080/example.com
curl -sS --retry 10 --retry-all-errors --retry-delay 1 -o /dev/null -u bob@example.com:bobpass "imap://127.0.0.1:8081/INBOX;UID=1"
curl -sS -u ann@example.com:annpass "imap://127.0.0.1:8081/INBOX?SUBJECT%20%22Cannot%20log%20in%22" --next -sS -u bob@example.com:bobpass "imap://127.0.0.1:8081/INBOX?SUBJECT%20%22Cannot%20log%20in%22"
kill $(jobs -p)
